files.patch:
Index: style.css
===================================================================
--- style.css
+++ style.css
@@ -1,6 +1,6 @@
 body { font-family: sans-serif; margin: 0; }
 main { padding: 24px; }
-.card { border: 1px solid #ddd; border-radius: 8px; padding: 16px; }
+.card { border: 1px solid #ddd; border-radius: 8px; padding: 16px; padding-left: 32px; }
 .btn { background: #2563eb; color: white; border: 0; padding: 8px 16px; border-radius: 6px; }
 footer { padding: 16px 24px; border-top: 1px solid #eee; }
 footer a { margin-right: 12px; }

content.text:
footer { padding: 16px 24px; border-top: 1px solid #eee; }
footer a { margin-right: 12px; }
@media (max-width: 639px) { footer { display: none; } }

